const employees=[
 {name:'Aarav Kumar',role:'Product Designer',team:'Design',manager:'Rohan Patel',initials:'AK',color:'avatar-purple',status:'Working',checkIn:'09:02 AM',hours:'06h 24m'},
 {name:'Meera Shah',role:'Frontend Developer',team:'Engineering',manager:'Rohan Patel',initials:'MS',color:'avatar-blue',status:'On break',checkIn:'08:56 AM',hours:'06h 31m'},
 {name:'Rohan Patel',role:'Product Manager',team:'Product',initials:'RP',color:'avatar-green',status:'Working',checkIn:'09:18 AM',hours:'06h 08m'},
 {name:'Ananya Rao',role:'People Partner',team:'People',initials:'AR',color:'avatar-pink',status:'Checked out',checkIn:'08:47 AM',hours:'08h 02m'},
 {name:'Kabir Singh',role:'QA Engineer',team:'Engineering',manager:'Rohan Patel',initials:'KS',color:'avatar-orange',status:'Absent',checkIn:'—',hours:'—'}
];
const navItems=[['dashboard','▦','Dashboard'],['attendance','◷','Attendance'],['leave','◌','Leave & WFH'],['tasks','☑','Task Manager'],['policies','▤','Policies'],['news','◈','News & Events'],['organization','⌘','Organization chart'],['resignation','↗','Resignation']];
let role='Employee',page='dashboard',attendanceState='Not checked in',clockedInAt='—',breakMinutes=0,workMode='Office',selectedShift='Shift 1',teamShiftMode='EMPLOYEE_SELECT',approvedWfhToday=true,pendingRegularization=false,toastTimer;
const roleAttendance={Employee:{state:'Not checked in',clock:'—',breakMinutes:0},Manager:{state:'Working',clock:'09:32 AM',breakMinutes:24},HR:{state:'Working',clock:'08:47 AM',breakMinutes:18},Admin:{state:'Not checked in',clock:'—',breakMinutes:0}};
let attendanceFilters={search:'',team:'All teams',status:'All statuses'};
const $=s=>document.querySelector(s),content=$('#content'),modal=$('#modal');
modal.addEventListener('close',()=>{modal.dataset.flow=''});
function dateLabel(){return new Intl.DateTimeFormat('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date())}
function nav(){ $('#navigation').innerHTML=navItems.map(([id,icon,label])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}"><span class="nav-icon">${icon}</span>${label}${id==='tasks'&&isManagement()?'<span class="nav-count">3</span>':''}</button>`).join('') }
function isManagement(){return ['Manager','HR','Admin'].includes(role)}
function canEditAll(){return ['HR','Admin'].includes(role)}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${isManagement()?'PEOPLE OPERATIONS':'YOUR WORKSPACE'}</div><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`}
function btn(text,action,primary=false){return `<button class="btn ${primary?'btn-primary':''}" data-action="${action}">${text}</button>`}
function stat(label,value,note,symbol='◷',tone=''){return `<div class="card stat-card"><div class="stat-top">${label}<span class="stat-symbol ${tone}">${symbol}</span></div><div class="stat-number">${value}</div><div class="stat-foot">${note}</div></div>`}
function person(name,roleText,initials,color='avatar-purple'){return `<div class="employee-cell"><span class="avatar ${color}">${initials}</span><span><strong>${name}</strong><small>${roleText}</small></span></div>`}
function statusBadge(s){let c=s==='Working'||s==='Approved'||s==='Completed'?'green':s==='On break'||s==='Pending'?'amber':s==='Not started'?'gray':s==='In progress'?'purple':s==='Absent'?'red':'gray';return `<span class="badge badge-${c}">${s}</span>`}
function liveCard(){let state=attendanceState==='Working'?'You’re checked in':attendanceState==='On break'?'You’re on a break':attendanceState==='Incomplete'?'Punch needs attention':attendanceState==='Absent'?'Marked absent':attendanceState==='Checked out'?'You’re checked out':'Ready to check in';let lockNote=pendingRegularization?'Your next check-in is locked until your manager approves the missed-punch correction.':attendanceState==='Absent'?'This shift has ended. Check-in is closed for today.':'';return `<div class="card live-card section-card"><div class="live-info"><span class="live-label">TODAY · ${dateLabel()}</span><div class="live-state">${state}</div><div class="live-time">${attendanceState==='Checked out'?'Your day is complete':attendanceState==='Not checked in'?`Shift ${selectedShift} · ${selectedShift==='Shift 1'?'09:30–18:30':'13:00–22:00'}`:`Since ${clockedInAt} · ${workMode} · Live status`}</div>${lockNote?`<div class="notice" style="margin-top:12px">${lockNote}</div>`:''}<div class="live-controls">${attendanceState==='Not checked in'&&!pendingRegularization?btn('Check in','checkin',true):attendanceState==='Working'?`${btn('Break in','break')}${btn('Check out','checkout',true)}`:attendanceState==='On break'?btn('Break out','endbreak',true):attendanceState==='Checked out'?'<span class="badge badge-green">Day complete ✓</span>':attendanceState==='Incomplete'?btn('Regularize missed punch','regularize',true):attendanceState==='Absent'?'<span class="badge badge-red">Check-in closed</span>':''}</div></div><div class="live-stats"><div><span>WORKED</span><strong>${attendanceState==='Checked out'?'08h 00m':attendanceState==='Not checked in'?'00h 00m':'06h 24m'}</strong></div><div><span>BREAK TIME</span><strong>${String(Math.floor(breakMinutes/60)).padStart(2,'0')}h ${String(breakMinutes%60).padStart(2,'0')}m <small style="font:10px 'DM Sans';color:#999">/ 1h</small></strong></div><div><span>SHIFT</span><strong>${selectedShift==='Shift 1'?'09:30 — 18:30':'13:00 — 22:00'}</strong></div></div><div class="progress"><span style="width:${Math.min(100,attendanceState==='Checked out'?100:attendanceState==='Not checked in'?0:78)}%"></span></div></div>`}
function timeline(){return `<div class="card section-card"><div class="card-header"><div><h2>Today’s timeline</h2><p>Your attendance at a glance</p></div><span class="badge badge-green">● Live</span></div><div class="timeline"><span class="timeline-time">09:02 AM</span><span class="timeline-track"><i class="timeline-dot"></i><i class="timeline-line active"></i></span><span class="timeline-type">Check in</span></div><div class="timeline"><span class="timeline-time">12:30 PM</span><span class="timeline-track"><i class="timeline-dot" style="background:#b6a9f3"></i><i class="timeline-line active"></i></span><span class="timeline-type">Break</span></div><div class="timeline"><span class="timeline-time">12:54 PM</span><span class="timeline-track"><i class="timeline-dot" style="background:#b6a9f3"></i><i class="timeline-line"></i></span><span class="timeline-type">Resumed</span></div><div class="timeline"><span class="timeline-time">—</span><span class="timeline-track"><i class="timeline-line"></i><i class="timeline-dot" style="background:#ddd"></i></span><span class="timeline-type">Check out</span></div></div>`}
function leaveBalance(){return `<div class="card balance-card section-card"><div class="card-header"><div><h2>Your leave balance</h2><p>Financial year 2026–27</p></div><span class="badge" style="background:#ffffff2b;color:#fff">Updated today</span></div><div class="balance-number">8.5 <span style="font:500 13px 'DM Sans'">days</span></div><div class="balance-caption">available to plan some time for you</div><div class="balance-split"><div><span>CASUAL LEAVE</span><strong>4.5 days</strong></div><div><span>SICK LEAVE</span><strong>4 days</strong></div></div></div>`}
function taskRows(){return `<div class="mini-list"><div class="mini-item"><span class="mini-icon">✦</span><div><strong>Finalize Q4 design system</strong><small>Due today · Assigned by Rohan</small></div>${statusBadge('In progress')}</div><div class="mini-item"><span class="mini-icon">▣</span><div><strong>Review onboarding flow</strong><small>Due Oct 28 · Assigned by Rohan</small></div>${statusBadge('Not started')}</div></div>`}
function eventRows(){return `<div class="mini-item event-card"><div class="event-date"><strong>28</strong><small>Oct</small></div><span class="event-photo">🎉</span><div class="event-copy"><strong>Diwali get-together</strong><small>Friday · 5:00 PM · The Terrace</small></div></div>`}
function dashboard(){let management=isManagement();return `${heading(management?`Good morning, ${role}`:'Good morning, Aarav',`${dateLabel()} · Here’s what’s happening today`,management?btn('Add employee','addemployee',true):btn('Apply for leave','applyleave',true))}${management?`<div class="grid stats-grid">${stat('PRESENT TODAY','42 / 48','87% of your team','✓')}${stat('ON LEAVE','3 employees','Across 2 departments','◌')}${stat('LATE ARRIVALS','2 employees','Today so far','↗')}${stat('PENDING APPROVALS','5 requests','Needs your attention','⌛')}</div>`:`<div class="grid stats-grid">${stat('WORKING DAYS','18 days','This month · 22 working days','▦')}${stat('LEAVE TAKEN','0.5 days','1 day accrued this month','◌')}${stat('LATE ARRIVALS','1 day','This month','↗')}${stat('PERMISSION LEFT','1h 30m','Of 2h monthly allowance','⌛')}</div>`}<div class="grid dashboard-grid"><div>${management?`<div class="card section-card"><div class="card-header"><div><h2>Team attendance</h2><p>Live overview · Today</p></div><button class="link-button" data-page="attendance">View all →</button></div>${employeeTable(employees.slice(0,4),true)}</div>`:liveCard()}${management?`<div class="card section-card"><div class="card-header"><div><h2>Needs your attention</h2><p>Review and respond to requests</p></div><span class="badge badge-amber">5 pending</span></div>${requestMini()}</div>`:timeline()}<div class="card section-card"><div class="card-header"><div><h2>My tasks</h2><p>Keep your priorities moving</p></div><button class="link-button" data-page="tasks">All tasks →</button></div>${taskRows()}</div></div><div>${management?`<div class="card section-card"><div class="card-header"><div><h2>My attendance</h2><p>Today · 09:00 AM – 06:00 PM</p></div></div>${liveCard()}</div>`:leaveBalance()}<div class="card section-card"><div class="card-header"><div><h2>Upcoming event</h2><p>Something to look forward to</p></div><button class="link-button" data-page="news">See all →</button></div>${eventRows()}</div><div class="card section-card"><div class="card-header"><div><h2>Latest news</h2><p>From your company</p></div><button class="link-button" data-page="news">View all →</button></div><div class="mini-item"><span class="mini-icon">✳</span><div><strong>Welcome to our new workspace</strong><small>People team · 2 days ago</small></div></div></div></div></div>`}
function employeeTable(list,showStatus=false){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>EMPLOYEE</th><th>CHECK IN</th><th>WORKED</th><th>STATUS</th>${showStatus?'<th>TEAM</th>':''}</tr></thead><tbody>${list.map(e=>`<tr><td>${person(e.name,e.role,e.initials,e.color)}</td><td>${e.checkIn}</td><td>${e.hours}</td><td>${statusBadge(e.status)}</td>${showStatus?`<td>${e.team}</td>`:''}</tr>`).join('')}</tbody></table></div>`}
function requestMini(){return `<div class="request-item"><span class="mini-icon">◌</span><div class="item-main"><strong>Casual leave · Meera Shah</strong><small>Oct 29 · 1 day</small></div>${statusBadge('Pending')}<button class="icon-action" data-action="approve">Review</button></div><div class="request-item"><span class="mini-icon">◷</span><div class="item-main"><strong>${pendingRegularization?'Missed punch · Aarav Kumar':'Missed punch · Rohan Patel'}</strong><small>Check-out correction · awaiting team manager</small></div>${statusBadge('Pending')}<button class="icon-action" data-action="approveregularization">Review</button></div>`}
function attendancePage(){let management=isManagement();return `${heading('Attendance',management?'Monitor your team’s attendance and working hours.':'Your attendance, all in one place.',management?btn('Export report','export'):btn(pendingRegularization?'Regularize missed punch':'Regularize a punch','regularize',true))}${management?`<div class="card-header"><div><h2>My attendance</h2><p>Your own check-in, breaks and check-out</p></div></div>${liveCard()}<div class="filter-row"><input class="field search-field" placeholder="Search employees…" id="employeeSearch"><select class="filter-select"><option>All departments</option><option>Engineering</option><option>Design</option><option>Product</option></select><select class="filter-select"><option>All statuses</option><option>Working</option><option>On break</option><option>Absent</option></select><span class="toolbar-note">Shift 1 default · Shift 2 enabled for selected teams</span><select class="filter-select" id="shiftMode"><option value="EMPLOYEE_SELECT" ${teamShiftMode==='EMPLOYEE_SELECT'?'selected':''}>Employees select shift</option><option value="MANAGER_ASSIGNED" ${teamShiftMode==='MANAGER_ASSIGNED'?'selected':''}>Manager assigns shifts</option></select></div><div class="card section-card"><div class="card-header"><div><h2>Team attendance</h2><p>Shift 1 · 09:30–18:30 &nbsp; | &nbsp; Shift 2 · 13:00–22:00</p></div><span class="badge badge-green">● Updating live</span></div>${employeeTable(employees,true)}</div>`:`${liveCard()}<div class="notice">Late rule: up to 10 minutes after shift start is allowed three times per calendar month. After those uses, a punch within 10 minutes is late; more than 10 minutes late is always late.</div><div class="grid attendance-cards">${stat('TOTAL WORKED','112h 36m','This month · 18 days','◷')}${stat('TOTAL BREAK','14h 24m','18 days · 1h daily allowance','☕')}${stat('AVG. WORK / DAY','08h 02m','Target · 8 hours','↗')}${stat('LATE ARRIVALS','1 day','This month','⌛')}</div><div class="card section-card"><div class="month-strip"><div><div class="eyebrow">MONTHLY RECORD</div><strong>October 2026</strong></div><div class="month-nav"><button>‹</button><span>October 2026</span><button>›</button></div></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="calendar-head">${d}</div>`).join('')}${Array.from({length:35},(_,i)=>{let n=i-2;return n<1||n>31?'<div></div>':`<div class="calendar-day ${n===25?'today':''} ${n===7?'late':''} ${n===12?'leave':''}"><span class="day-number">${n}</span>${n<25&&n%7<5?`<br><span class="day-mark">${n===7?'Late':n===12?'Leave':'08h 00m'}</span>`:''}</div>`}).join('')}</div></div><div class="card section-card"><div class="card-header"><div><h2>Daily punch details</h2><p>Each break has its own time; total break allowance is 1 hour per day</p></div><span class="badge badge-purple">October</span></div><div class="timeline"><span class="timeline-time">09:30 AM</span><span class="timeline-track"><i class="timeline-dot"></i><i class="timeline-line active"></i></span><span class="timeline-type">Office check-in · location captured</span></div><div class="timeline"><span class="timeline-time">12:30 PM</span><span class="timeline-track"><i class="timeline-dot" style="background:#b6a9f3"></i><i class="timeline-line active"></i></span><span class="timeline-type">Break 1 · start</span></div><div class="timeline"><span class="timeline-time">12:54 PM</span><span class="timeline-track"><i class="timeline-dot" style="background:#b6a9f3"></i><i class="timeline-line"></i></span><span class="timeline-type">Break 1 · end</span></div><div class="timeline"><span class="timeline-time">—</span><span class="timeline-track"><i class="timeline-line"></i><i class="timeline-dot" style="background:#ddd"></i></span><span class="timeline-type">Check out · office location required</span></div></div>`}`}
function leavePage(){return `${heading('Leave, permission & WFH','Plan time away and keep your balances in view.',`${btn('New leave / permission','newrequest',true)}${btn('Request WFH','wfhrequest')}`)}<div class="grid split-grid"><div>${leaveBalance()}<div class="card section-card"><div class="card-header"><div><h2>Your requests</h2><p>Manager approval required · HR fallback only if manager unavailable</p></div><select class="filter-select"><option>All requests</option><option>Pending</option><option>Approved</option></select></div><div class="request-item"><span class="mini-icon">◌</span><div class="item-main"><strong>Casual leave · 1 day</strong><small>Oct 29, 2026 · Submitted Oct 21</small></div>${statusBadge('Pending')}</div><div class="request-item"><span class="mini-icon">⌂</span><div class="item-main"><strong>Work from home · 2 days</strong><small>Oct 14–15, 2026 · Approved by Rohan</small></div>${statusBadge('Approved')}</div><div class="request-item"><span class="mini-icon">◷</span><div class="item-main"><strong>Permission · 30 minutes</strong><small>Oct 08, 2026</small></div>${statusBadge('Approved')}</div></div></div><div><div class="card section-card"><div class="card-header"><div><h2>Monthly allowances</h2><p>Available for October</p></div></div><div class="shift-row"><strong>Permission</strong><span>1h 30m / 2h left</span></div><div class="progress"><span style="width:25%"></span></div><div class="shift-row" style="margin-top:18px"><strong>Work from home</strong><span>2 / 4 days used</span></div><div class="progress"><span style="width:50%;background:#53ae8c"></span></div><p class="toolbar-note" style="line-height:1.6;margin-top:14px">Permission and WFH have separate monthly limits. Your team manager approves requests; HR handles them only if the manager is unavailable.</p></div><div class="card section-card"><div class="card-header"><div><h2>Leave policy</h2><p>Financial year 2026–27</p></div><button class="link-button" data-page="policies">Read policy →</button></div><div class="shift-row"><span>Monthly accrual</span><strong>1 day</strong></div><div class="shift-row"><span>Casual leave</span><strong>0.5 day / month</strong></div><div class="shift-row"><span>Sick leave</span><strong>0.5 day / month</strong></div><div class="shift-row"><span>Full-day notice</span><strong>Before leave date</strong></div><div class="shift-row"><span>Half-day</span><strong>Same-day allowed</strong></div><div class="shift-row"><span>Carry forward</span><strong>Separate CL / SL</strong></div></div></div></div>`}
const tasks=[{title:'Finalize Q4 design system',assignee:'Aarav Kumar',due:'Oct 25',status:'In progress',assigned:'Rohan Patel'},{title:'Review onboarding flow',assignee:'Aarav Kumar',due:'Oct 28',status:'Not started',assigned:'Rohan Patel'},{title:'Prepare sprint handoff notes',assignee:'Meera Shah',due:'Oct 29',status:'Pending',assigned:'Rohan Patel'},{title:'Update component library',assignee:'Aarav Kumar',due:'Oct 22',status:'Completed',assigned:'Meera Shah'}];
function tasksPage(){return `${heading('Task Manager','Assignments and progress, all in one view.',isManagement()?btn('Assign a task','newtask',true):'')}<div class="filter-row"><input class="field search-field" placeholder="Search tasks…"><select class="filter-select"><option>All statuses</option><option>Not started</option><option>In progress</option><option>Pending</option><option>Completed</option></select>${isManagement()?'<select class="filter-select"><option>All employees</option><option>Aarav Kumar</option><option>Meera Shah</option></select>':''}</div><div class="card section-card"><div class="card-header"><div><h2>${isManagement()?'Team tasks':'My tasks'}</h2><p>${isManagement()?'Monitor assignments and unblock work.':'Tasks assigned to you by your manager.'}</p></div><span class="badge badge-purple">${tasks.length} tasks</span></div>${tasks.filter(t=>role!=='Employee'||t.assignee==='Aarav Kumar').map(t=>`<div class="task-item"><span class="mini-icon">☑</span><div class="item-main"><strong>${t.title}</strong><small>${isManagement()?`Assigned to ${t.assignee} · `:''}Due ${t.due} · Assigned by ${t.assigned}</small></div><select class="filter-select task-status" data-task="${t.title}">${['Not started','In progress','Pending','Completed'].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select>${t.status==='Pending'?'<span class="badge badge-amber" title="Waiting for clarification">Waiting on info</span>':''}</div>`).join('')}</div><div class="notice">Pending means a task is waiting on something (for example, approval or clarification). Add a short reason when moving a task to Pending.</div>`}
function policiesPage(){let edit=canEditAll();return `${heading('Company policies','A clear guide to how we work together.',edit?btn('Add policy','newpolicy',true):'')}<div class="card section-card"><div class="card-header"><div><h2>Published policies</h2><p>Current company guidelines · Updated October 2026</p></div><span class="badge badge-green">${edit?'HR & Admin can edit':'Read only'}</span></div>${[['Attendance & punctuality','Work hours, check-ins, breaks and attendance regularization.','Oct 12, 2026'],['Leave, permission & WFH','Monthly allowances, approvals and carry-forward rules.','Oct 10, 2026'],['Code of conduct','Our shared principles for a respectful workplace.','Sep 22, 2026'],['Information security','Keeping company and customer information safe.','Aug 18, 2026']].map(([a,b,c])=>`<div class="policy-item"><span class="mini-icon">▤</span><div class="item-main"><strong>${a}</strong><small>${b}</small><small style="margin-top:5px">Updated ${c}</small></div><button class="btn btn-soft" data-action="readpolicy">Read policy</button>${edit?'<button class="icon-action" data-action="editpolicy">Edit</button>':''}</div>`).join('')}</div>`}
function newsPage(){let edit=isManagement();return `${heading('News & Events','What’s happening across our company.',edit?btn('Post an update','newnews',true):'')}<div class="grid split-grid"><div class="card section-card"><div class="card-header"><div><h2>Company news</h2><p>Updates from your people and leadership teams</p></div></div>${[['A new chapter for our workspace','We’re excited to share our refreshed collaboration space. Come by and make yourself at home.','People team · 2 days ago','✳'],['October all-hands recap','A few highlights, key decisions and what’s coming next for the team.','Leadership · Oct 20','◈'],['Benefits enrollment is open','Review your options and submit your selections by November 15.','People team · Oct 18','♡']].map(([a,b,c,d])=>`<div class="news-card"><div class="news-art">${d}</div><div class="news-body"><strong>${a}</strong><p>${b}</p><small>${c}</small>${edit?'<div class="item-actions" style="margin-top:8px"><button class="icon-action" data-action="editnews">Edit</button><button class="icon-action" data-action="publish">Published</button></div>':''}</div></div>`).join('')}</div><div><div class="card section-card"><div class="card-header"><div><h2>Upcoming events</h2><p>Mark your calendar</p></div>${canEditAll()?'<button class="link-button" data-action="newevent">+ Add</button>':''}</div><div class="event-card"><div class="event-date"><strong>28</strong><small>Oct</small></div><span class="event-photo">🎉</span><div class="event-copy"><strong>Diwali get-together</strong><small>5:00 PM · The Terrace</small></div></div><div class="toolbar-note" style="margin:10px 0 18px">An evening of food, lights and good company.</div><div class="event-card"><div class="event-date"><strong>07</strong><small>Nov</small></div><span class="event-photo">🎤</span><div class="event-copy"><strong>Quarterly all-hands</strong><small>11:00 AM · Main hall</small></div></div><div class="toolbar-note" style="margin:10px 0 0">Company updates and open Q&amp;A.</div></div><div class="card section-card"><div class="card-header"><div><h2>Past events</h2><p>Good moments we’ve shared</p></div></div><div class="event-card"><div class="event-date"><strong>02</strong><small>Oct</small></div><span class="event-photo">🏆</span><div class="event-copy"><strong>Founders’ Day</strong><small>Photos · 12 moments</small></div></div></div></div></div>`}
const org=['Aarav Kumar','Meera Shah','Rohan Patel','Ananya Rao','Kabir Singh'];
function organizationPage(){let editable=canEditAll();return `${heading('Organization chart','Meet your people and see how teams connect.',editable?btn('Edit organization','editorg',true):'')}<div class="grid split-grid"><div class="card section-card"><div class="card-header"><div><h2>Company structure</h2><p>5 employees · 4 teams</p></div><select class="filter-select"><option>All departments</option><option>Engineering</option><option>Design</option></select></div><div class="org-tree"><div class="org-node">${person('Ananya Rao','People Partner · HR','AR','avatar-pink')}</div><div class="org-connector"></div><div class="org-node">${person('Rohan Patel','Product Manager · Manager','RP','avatar-green')}</div><div class="org-connector"></div><div class="org-children"><div class="org-column"><div class="org-node">${person('Aarav Kumar','Product Designer','AK','avatar-purple')}</div></div><div class="org-column"><div class="org-node">${person('Meera Shah','Frontend Developer','MS','avatar-blue')}</div></div><div class="org-column"><div class="org-node">${person('Kabir Singh','QA Engineer','KS','avatar-orange')}</div></div></div></div></div><div class="card section-card"><div class="card-header"><div><h2>People directory</h2><p>Employees across your company</p></div></div>${employees.map(e=>`<div class="request-item">${person(e.name,e.team+' · '+e.role,e.initials,e.color)}${editable?'<button class="icon-action" data-action="editperson">Edit</button>':''}</div>`).join('')}</div></div>`}
function resignationPage(){return `${heading('Resignation','Submit or review a resignation request.',role==='Employee'?btn('Submit resignation','resign',true):'')}<div class="grid split-grid"><div class="card section-card"><div class="card-header"><div><h2>${role==='Employee'?'Your resignation request':'Resignation requests'}</h2><p>Requests require review by the team manager and HR.</p></div></div>${role==='Employee'?`<div class="notice">If you’re considering a change, your manager or people partner is available to talk.</div><div class="request-item"><span class="mini-icon">↗</span><div class="item-main"><strong>No active resignation request</strong><small>Any request you submit will be visible to your manager and HR.</small></div>${statusBadge('No request')}</div>`:`<div class="request-item">${person('Meera Shah','Frontend Developer · Engineering','MS','avatar-blue')}<div class="item-main"><strong>Proposed last day · Nov 30</strong><small>Submitted Oct 22 · “Personal reasons”</small></div>${statusBadge('Pending')}<button class="icon-action" data-action="reviewresign">Review</button></div>`}</div><div class="card section-card"><div class="card-header"><div><h2>How it works</h2><p>Your request will go through these steps</p></div></div><div class="shift-row"><strong>1. Submit request</strong><span>Employee submits details</span></div><div class="shift-row"><strong>2. Manager review</strong><span>Team manager considers</span></div><div class="shift-row"><strong>3. HR review</strong><span>HR confirms next steps</span></div><div class="shift-row"><strong>4. Decision shared</strong><span>Status is updated</span></div></div></div>`}
function scopedEmployees(){if(role==='Employee')return employees.filter(e=>e.name==='Aarav Kumar');if(role==='Manager')return employees.filter(e=>e.manager==='Rohan Patel');return employees}
function employeeTable(list,showStatus=false){if(!list.length)return '<div class="empty-state">No employees match these filters.</div>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>EMPLOYEE</th><th>CHECK IN</th><th>WORKED</th><th>STATUS</th>${showStatus?'<th>TEAM</th>':''}</tr></thead><tbody>${list.map(e=>`<tr><td>${person(e.name,e.role,e.initials,e.color)}</td><td>${e.checkIn}</td><td>${e.hours}</td><td>${statusBadge(e.status)}</td>${showStatus?`<td>${e.team}</td>`:''}</tr>`).join('')}</tbody></table></div>`}
function dashboard(){
 const team=scopedEmployees(), management=isManagement();
 if(role==='Employee')return `${heading('Good morning, Aarav',`${dateLabel()} · Here’s what’s happening today`,btn('Apply for leave','applyleave',true))}<div class="grid stats-grid">${stat('WORKING DAYS','18 days','This month · 22 working days','▦')}${stat('LEAVE TAKEN','0.5 days','1 day accrued this month','◌')}${stat('LATE ARRIVALS','1 day','This month','↗')}${stat('PERMISSION LEFT','1h 30m','Of 2h monthly allowance','⌛')}</div><div class="grid dashboard-grid"><div>${liveCard()}${timeline()}<div class="card section-card"><div class="card-header"><div><h2>My tasks</h2><p>Keep your priorities moving</p></div><button class="link-button" data-page="tasks">All tasks →</button></div>${taskRows()}</div></div><div>${leaveBalance()}<div class="card section-card"><div class="card-header"><div><h2>Upcoming event</h2><p>Something to look forward to</p></div><button class="link-button" data-page="news">See all →</button></div>${eventRows()}</div></div></div>`;
 if(role==='Manager')return `${heading('Good morning, Rohan','Manager workspace · Your own attendance and Engineering team',btn('Assign a task','newtask',true))}<div class="grid stats-grid">${stat('TEAM PRESENT',`${team.filter(e=>['Working','On break'].includes(e.status)).length} / ${team.length}`,'Your team today','✓')}${stat('ON LEAVE','1 employee','Engineering team','◌')}${stat('LATE ARRIVALS','1 employee','Your team today','↗')}${stat('PENDING APPROVALS','3 requests','Your team queue','⌛')}</div><div class="grid dashboard-grid"><div><div class="card-header"><div><h2>My attendance</h2><p>Manager self-service</p></div><button class="link-button" data-page="attendance">Open attendance →</button></div>${liveCard()}<div class="card section-card"><div class="card-header"><div><h2>My team attendance</h2><p>Only employees assigned to your team manager account</p></div><button class="link-button" data-page="attendance">View team →</button></div>${employeeTable(team,true)}</div></div><div><div class="card section-card"><div class="card-header"><div><h2>Team approvals</h2><p>Review requests from your team</p></div><span class="badge badge-amber">3 pending</span></div>${requestMini()}</div><div class="card section-card"><div class="card-header"><div><h2>Team tasks</h2><p>Assigned by you</p></div><button class="link-button" data-page="tasks">Manage →</button></div>${taskRows()}</div></div></div>`;
 if(role==='HR')return `${heading('People operations','Company-wide HR view · Attendance, requests and people records',btn('Add employee','addemployee',true))}<div class="grid stats-grid">${stat('ACTIVE EMPLOYEES','48','Across 6 teams','♙')}${stat('PRESENT TODAY','42','Company-wide','✓')}${stat('LEAVE TODAY','3 employees','Across 2 teams','◌')}${stat('HR QUEUE','7 requests','Fallbacks and HR reviews','⌛')}</div><div class="grid dashboard-grid"><div><div class="card section-card"><div class="card-header"><div><h2>Company attendance</h2><p>All teams · HR can review company records</p></div><button class="link-button" data-page="attendance">Open report →</button></div>${employeeTable(employees,true)}</div><div class="card section-card"><div class="card-header"><div><h2>My attendance</h2><p>HR self-service</p></div></div>${liveCard()}</div></div><div><div class="card section-card"><div class="card-header"><div><h2>HR actions</h2><p>Company-wide people operations</p></div></div>${requestMini()}<div class="shift-row"><span>Resignation reviews</span><strong>2 pending</strong></div></div><div class="card section-card"><div class="card-header"><div><h2>People content</h2><p>Policies and company communications</p></div></div><div class="shift-row"><span>Policies to publish</span><strong>2 drafts</strong></div><div class="shift-row"><span>Upcoming events</span><strong>3 scheduled</strong></div><button class="link-button" data-page="policies">Open policy manager →</button></div></div></div>`;
 return `${heading('Admin console','Full company access · People, teams, roles and activity',btn('Add employee','addemployee',true))}<div class="grid stats-grid">${stat('ACTIVE ACCOUNTS','52','48 employees · 4 admin roles','♙')}${stat('TEAMS','6','Manager assigned per team','⌘')}${stat('PENDING ITEMS','7','Approvals across company','⌛')}${stat('SYSTEM ACTIVITY','128 events','Last 7 days','↗')}</div><div class="grid dashboard-grid"><div><div class="card section-card"><div class="card-header"><div><h2>Company-wide attendance</h2><p>Admin access across every employee and team</p></div><button class="link-button" data-page="attendance">Manage attendance →</button></div>${employeeTable(employees,true)}</div><div class="card section-card"><div class="card-header"><div><h2>My attendance</h2><p>Admin self-service</p></div></div>${liveCard()}</div></div><div><div class="card section-card"><div class="card-header"><div><h2>Administration</h2><p>Full access and configuration</p></div></div><div class="shift-row"><span>Employee and role management</span><button class="icon-action" data-action="addemployee">Open</button></div><div class="shift-row"><span>Team and manager setup</span><button class="icon-action" data-page="organization">Open</button></div><div class="shift-row"><span>Policy and system audit</span><button class="icon-action" data-page="policies">Open</button></div></div><div class="card section-card"><div class="card-header"><div><h2>Recent activity</h2><p>Company-wide audit overview</p></div></div><div class="mini-item"><span class="mini-icon">✓</span><div><strong>Leave request approved</strong><small>Rohan Patel · 18 minutes ago</small></div></div><div class="mini-item"><span class="mini-icon">◷</span><div><strong>Shift assignment updated</strong><small>Engineering · Today</small></div></div></div></div></div>`;
}
function attendanceFilterMarkup(list){let teams=[...new Set(list.map(e=>e.team))];return `<div class="filter-row"><input class="field search-field" placeholder="Search employees…" id="employeeSearch" value="${attendanceFilters.search}"><select class="filter-select" id="departmentFilter"><option>All teams</option>${teams.map(t=>`<option ${attendanceFilters.team===t?'selected':''}>${t}</option>`).join('')}</select><select class="filter-select" id="statusFilter">${['All statuses','Working','On break','Absent','Checked out','Not checked in'].map(s=>`<option ${attendanceFilters.status===s?'selected':''}>${s}</option>`).join('')}</select><span class="toolbar-note" id="attendanceResultCount"></span></div>`}
function applyAttendanceFilters(){let list=scopedEmployees(),q=attendanceFilters.search.toLowerCase();if(q)list=list.filter(e=>`${e.name} ${e.role} ${e.team}`.toLowerCase().includes(q));if(attendanceFilters.team!=='All teams')list=list.filter(e=>e.team===attendanceFilters.team);if(attendanceFilters.status!=='All statuses')list=list.filter(e=>e.status===attendanceFilters.status);let wrap=$('#attendanceTableWrap');if(wrap)wrap.innerHTML=employeeTable(list,true);let count=$('#attendanceResultCount');if(count)count.textContent=`Showing ${list.length} of ${scopedEmployees().length}`}
function attendancePage(){if(role==='Employee')return `${heading('Attendance','Your personal attendance history and punch controls.',btn(pendingRegularization?'Regularize missed punch':'Regularize a punch','regularize',true))}${liveCard()}<div class="notice">Late rule: 10-minute grace, three uses per month. Arrivals beyond 10 minutes are late; after the three uses, arrivals within the grace window are late too.</div><div class="grid attendance-cards">${stat('TOTAL WORKED','112h 36m','This month · 18 days','◷')}${stat('TOTAL BREAK','14h 24m','Multiple intervals · 1h allowance','☕')}${stat('AVG. WORK / DAY','08h 02m','Target · 8 hours','↗')}${stat('LATE ARRIVALS','1 day','This month','⌛')}</div><div class="card section-card"><div class="month-strip"><div><div class="eyebrow">MONTHLY RECORD</div><strong>October 2026</strong></div><div class="month-nav"><button>‹</button><span>October 2026</span><button>›</button></div></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="calendar-head">${d}</div>`).join('')}${Array.from({length:35},(_,i)=>{let n=i-2;return n<1||n>31?'<div></div>':`<div class="calendar-day ${n===25?'today':''} ${n===7?'late':''} ${n===12?'leave':''}"><span class="day-number">${n}</span>${n<25&&n%7<5?`<br><span class="day-mark">${n===7?'Late':n===12?'Leave':'08h 00m'}</span>`:''}</div>`}).join('')}</div></div><div class="card section-card"><div class="card-header"><div><h2>Daily punch details</h2><p>Each break has its own start and end time; total daily allowance is 1 hour</p></div></div><div class="timeline"><span class="timeline-time">09:30 AM</span><span class="timeline-track"><i class="timeline-dot"></i><i class="timeline-line active"></i></span><span class="timeline-type">Office check-in · location captured</span></div><div class="timeline"><span class="timeline-time">12:30 PM</span><span class="timeline-track"><i class="timeline-dot" style="background:#b6a9f3"></i><i class="timeline-line active"></i></span><span class="timeline-type">Break in</span></div><div class="timeline"><span class="timeline-time">12:54 PM</span><span class="timeline-track"><i class="timeline-dot" style="background:#b6a9f3"></i><i class="timeline-line"></i></span><span class="timeline-type">Break out</span></div><div class="timeline"><span class="timeline-time">13:40 PM</span><span class="timeline-track"><i class="timeline-dot" style="background:#b6a9f3"></i><i class="timeline-line"></i></span><span class="timeline-type">Break in 2</span></div><div class="timeline"><span class="timeline-time">14:05 PM</span><span class="timeline-track"><i class="timeline-dot" style="background:#b6a9f3"></i><i class="timeline-line"></i></span><span class="timeline-type">Break out 2</span></div></div>`;let scope=role==='Manager'?'Your team only':role==='HR'?'Company-wide HR scope':'Full company admin scope';return `${heading(role==='Manager'?'Attendance':'Company attendance',role==='Manager'?'Your own punches and your team’s attendance.':role==='HR'?'HR attendance view · All employees and teams.':'Admin attendance console · Full company access.',role==='Admin'?btn('Export report','export'):role==='HR'?btn('HR attendance report','export'):btn('Export team report','export'))}<div class="card-header"><div><h2>My attendance</h2><p>Your personal punch and break controls remain available</p></div><span class="badge badge-purple">${scope}</span></div>${liveCard()}${role==='Manager'?'<div class="notice">You can view records, approve requests, and manage attendance for your team only. This sample manager account is assigned to Aarav, Meera, and Kabir.</div>':role==='HR'?'<div class="notice">HR can review attendance company-wide and handle requests routed here when a manager is unavailable.</div>':'<div class="notice">Admin can view and manage every employee and team attendance record.</div>'}${attendanceFilterMarkup(scopedEmployees())}<div class="card section-card"><div class="card-header"><div><h2>${role==='Manager'?'My team attendance':role==='HR'?'Company attendance - HR view':'All employee attendance'}</h2><p>${scope} · Shift 1 09:30–18:30 · Shift 2 13:00–22:00</p></div><span class="badge badge-green">● Live sample</span></div><div id="attendanceTableWrap">${employeeTable(scopedEmployees(),true)}</div></div>${role==='Admin'?'<div class="card section-card"><div class="card-header"><div><h2>Admin controls</h2><p>Configuration across the company</p></div></div><button class="btn" data-page="organization">Manage teams and managers</button> <button class="btn" data-page="policies">Manage policies</button></div>':''}`}
function render(){nav();let title=navItems.find(x=>x[0]===page)?.[2]||'Dashboard';$('#pageCrumb').textContent=title;const pages={dashboard,attendance:attendancePage,leave:leavePage,tasks:tasksPage,policies:policiesPage,news:newsPage,organization:organizationPage,resignation:resignationPage};content.innerHTML=pages[page]();$('#profileRole').textContent=role;$('#profileName').textContent=role==='Employee'?'Aarav Kumar':role==='Manager'?'Rohan Patel':role==='HR'?'Ananya Rao':'Admin User';document.querySelectorAll('.top-avatar').forEach(a=>a.textContent=role==='Employee'?'AK':role==='Manager'?'RP':role==='HR'?'AR':'AD');}
const renderBase=render;render=function(){roleAttendance[role]={state:attendanceState,clock:clockedInAt,breakMinutes};renderBase();if(page==='attendance'&&role!=='Employee')applyAttendanceFilters()};
function toast(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function modalForm(title,desc,fields,submit){$('#modalContent').innerHTML=`<div class="eyebrow">ATTEND · WORKSPACE</div><h2>${title}</h2><p>${desc}</p><div class="request-form">${fields}</div><div class="modal-actions"><button class="btn" value="cancel">Cancel</button><button class="btn btn-primary" data-action="submitmodal">${submit}</button></div>`;modal.showModal()}
function input(label,name,type='text',placeholder=''){return `<div class="form-field"><label>${label}</label><input name="${name}" type="${type}" placeholder="${placeholder}" required></div>`}
function select(label,name,opts){return `<div class="form-field"><label>${label}</label><select name="${name}">${opts.map(o=>`<option>${o}</option>`).join('')}</select></div>`}
function actions(e){let a=e.target.closest('[data-action]')?.dataset.action;if(!a)return;
if(a==='checkin'){if(pendingRegularization){toast('Check-in locked. Your manager must approve the missed-punch correction first.');return}if(attendanceState==='Absent'){toast('This shift has ended; check-in is closed.');return}let shiftPicker=teamShiftMode==='EMPLOYEE_SELECT'?select('SHIFT','shift',['Shift 1 · 09:30–18:30','Shift 2 · 13:00–22:00']):`<div class="notice">Your team manager assigned <strong>${selectedShift}</strong> · ${selectedShift==='Shift 1'?'09:30–18:30':'13:00–22:00'}</div><input type="hidden" name="shift" value="${selectedShift} · ${selectedShift==='Shift 1'?'09:30–18:30':'13:00–22:00'}">`;modalForm('Check in','Choose your work location. Office punches require location permission; WFH does not collect location.',`${select('WORK MODE','workMode',['Office','WFH'])}${shiftPicker}<div class="notice">WFH check-in requires an approved WFH request for today. Sample status: Approved.</div><label class="photo-upload" style="display:block;text-align:left"><input type="checkbox" name="locationPermission" style="display:inline;width:auto"> I allow precise location for this Office punch</label><div class="toolbar-note">Location is requested only for Office check-in/check-out. This prototype simulates location permission; it does not read or store GPS.</div>`,'Check in');modal.dataset.flow='checkin'}
else if(a==='checkout'){modalForm('Check out','Finish your workday. Office check-out requires precise location permission; WFH does not collect location.',`<div class="notice">Current work mode: ${workMode}</div>${workMode==='Office'?'<label class="photo-upload" style="display:block;text-align:left"><input type="checkbox" name="locationPermission" style="display:inline;width:auto"> I allow precise location for this Office punch</label>':'<div class="toolbar-note">No location will be requested for this WFH punch.</div>'}`,'Check out');modal.dataset.flow='checkout'}
else if(a==='break'){attendanceState='On break';render();toast('Break started. All break periods are tracked toward the daily 1-hour allowance.')}
else if(a==='endbreak'){breakMinutes=Math.min(90,breakMinutes+24);attendanceState='Working';render();toast(breakMinutes>60?'Break ended. HR will review time above the 1-hour daily allowance.':'Break ended. Welcome back!')}
else if(a==='done'){toast('You have already checked out for today.')}
else if(a==='regularize'){modalForm('Regularize a missed punch','Enter the missing check-out time and reason. Your next check-in stays locked until your team manager approves.',`${input('Date','date','date')}${input('Correct check-out time','time','time')}<div class="form-field"><label>Reason</label><textarea name="reason" placeholder="What happened?" required></textarea></div><div class="notice">No submission deadline. Approval is required before your next check-in.</div>`,'Submit for approval');modal.dataset.flow='regularize'}
else if(a==='applyleave'||a==='newrequest')modalForm('New leave or permission request','Your team manager approves requests. HR is the fallback only if the manager is unavailable.',`${select('REQUEST TYPE','type',['Casual leave','Sick leave','Permission'])}<div class="form-row">${input('Start date','start','date')}${input('End date','end','date')}</div><div id="leaveDurationFields">${select('LEAVE DURATION','duration',['Full day','Half day'])}<div id="halfDayDetails" class="form-row" hidden><div class="form-field"><label>Half-day start time</label><input name="halfStart" type="time"></div><div class="form-field"><label>Half-day end time</label><input name="halfEnd" type="time"></div>${select('HALF-DAY PERIOD','period',['First half','Second half'])}</div></div><div id="permissionDurationFields" hidden><div class="form-field"><label>Permission hours</label><input name="permissionHours" type="number" min="0.25" step="0.25" placeholder="e.g. 0.5"></div></div><div class="form-field"><label>Reason</label><textarea name="reason" placeholder="Add a note for your approver"></textarea></div><div class="notice">Half-day leave reveals start/end timing. Same-day half-day requests require manager approval before leave begins. Full-day same-day requests are blocked; multi-day leave is full days only. WFH has its own request option and approval.</div>`,'Submit request');
else if(a==='wfhrequest'){modalForm('Request work from home','Choose the date(s). Your team manager approves; HR is the fallback only if the manager is unavailable.',`<div class="form-row">${input('WFH start date','start','date')}${input('WFH end date','end','date')}</div>${input('Reason','reason','text','Why do you need WFH?')}<div class="notice">Request before the requested date and within your team manager’s advance-notice cutoff. Limit: 4 days per month. Approved WFH can be selected at check-in; no location is collected.</div>`,'Submit WFH request');modal.dataset.flow='wfhrequest'}
else if(a==='newtask')modalForm('Assign a task','Give your teammate a clear outcome and due date.',`${input('Task title','title','text','What needs to be done?')}${select('Assign to','assignee',employees.map(x=>x.name))}<div class="form-row">${input('Due date','due','date')}${select('Priority','priority',['Normal','High','Urgent'])}</div><div class="form-field"><label>Details</label><textarea name="details" placeholder="Add helpful context"></textarea></div>`,'Assign task');
else if(a==='newpolicy'||a==='editpolicy')modalForm(a==='newpolicy'?'Add a policy':'Edit policy','HR and Admin can publish and update company policies.',`${input('Policy title','title','text','Policy name')}<div class="form-field"><label>Policy content</label><textarea name="content" placeholder="Write the policy details…" required></textarea></div>${select('Status','status',['Draft','Published'])}`,'Save policy');
else if(a==='newnews')modalForm('Post company news','Share an update with the people in your company.',`${input('Headline','title','text','What’s the update?')}<div class="form-field"><label>Message</label><textarea name="message" placeholder="Write your update…" required></textarea></div>${select('Publish status','status',['Publish now','Save as draft'])}`,'Publish update');
else if(a==='newevent')modalForm('Add a company event','Share an upcoming event or a moment from the past.',`${input('Event name','title','text','Event title')}<div class="form-row">${input('Date','date','date')}${input('Time','time','time')}</div>${input('Location','location','text','Where is it?')}<div class="form-field"><label>Description</label><textarea name="description" placeholder="Add event details"></textarea></div><label class="photo-upload">＋ &nbsp; Add event photos<input name="photos" type="file" accept="image/*" multiple></label>`,'Publish event');
else if(a==='editorg')toast('Organization editing is coming up next.');else if(a==='addemployee'||a==='editperson')modalForm('Employee details','Manage employee information and reporting lines.',`${input('Full name','name','text','Employee name')}${select('Department','team',['Engineering','Design','Product','People','Finance'])}${select('Reports to','manager',employees.map(x=>x.name))}`,'Save changes');
else if(a==='resign')modalForm('Submit resignation','This request will be reviewed by your team manager and HR.',`${input('Proposed last working day','lastday','date')}<div class="form-field"><label>Reason (optional)</label><textarea name="reason" placeholder="Share any context you’d like us to know"></textarea></div><div class="notice">Submitting a request starts the review process. HR will discuss next steps with you.</div>`,'Submit request');
else if(a==='approveregularization'&&pendingRegularization&&isManagement()){pendingRegularization=false;attendanceState='Not checked in';render();toast('Missed punch approved. Aarav can check in again.')}
else if(a==='reviewresign'||a==='approve')modalForm(a==='reviewresign'?'Review resignation':'Review request','Manager approval is normally sufficient. HR handles it only if the team manager is unavailable.',`${select('Decision','decision',['Approve','Decline','Request more information'])}<div class="form-field"><label>Note</label><textarea name="note" placeholder="Add a note"></textarea></div>`,'Save decision');
else if(a==='readpolicy')modalForm('Attendance & company policy','Policy preview · Last updated October 2026',`<div class="notice">Company policies are maintained by HR and Admin. Contact the People team with questions.</div><div class="form-field"><label>Policy summary</label><textarea readonly>Standard working day: 8 work hours with a 1-hour break. Attendance regularization requests must include the corrected punch time and a reason, and require team manager approval.</textarea></div>`,'Close');
else if(a==='export')toast('Attendance report prepared for export.');else if(a==='help')toast('Contact your People team at people@company.example');else if(a==='notifications')toast('You’re all caught up.');else if(a==='publish')toast('This update is published.');else if(a==='editnews')toast('News editing is ready to connect to saved data.');
}
document.addEventListener('click',e=>{let p=e.target.closest('[data-page]')?.dataset.page;if(p){page=p;$('#sidebar').classList.remove('open');render();return}actions(e)});
document.addEventListener('click',e=>{if(e.target.matches('[data-action="submitmodal"]')){e.preventDefault();let form=modal.querySelector('form');if(!form.reportValidity())return;let flow=modal.dataset.flow;if(flow==='checkin'){let mode=form.elements.workMode.value;let place=mode==='Office';if(place&&!form.elements.locationPermission.checked){toast('Allow precise location to record an Office punch.');return}if(mode==='WFH'&&!approvedWfhToday){toast('An approved WFH request is required for this date.');return}workMode=mode;selectedShift=form.elements.shift.value.startsWith('Shift 2')?'Shift 2':'Shift 1';attendanceState='Working';clockedInAt=new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'});breakMinutes=0;modal.close();render();toast(`${workMode} check-in recorded at ${clockedInAt}. ${place?'Location permission confirmed.':'No location collected for WFH.'}`);return}if(flow==='checkout'){if(workMode==='Office'&&!form.elements.locationPermission.checked){toast('Allow precise location to record an Office check-out.');return}attendanceState='Checked out';modal.close();render();toast(`Check-out recorded${workMode==='Office'?' with location permission':''}.`);return}if(flow==='regularize'){pendingRegularization=true;attendanceState='Incomplete';modal.close();render();toast('Regularization submitted. Your next check-in is locked pending manager approval.');return}modal.close();toast(flow==='wfhrequest'?'WFH request sent to your team manager for approval.':'Request submitted to your team manager for approval.')}});
$('#roleSelect').addEventListener('change',e=>{role=e.target.value;page='dashboard';attendanceFilters={search:'',team:'All teams',status:'All statuses'};let own=roleAttendance[role];attendanceState=own.state;clockedInAt=own.clock;breakMinutes=own.breakMinutes;pendingRegularization=false;render()});$('#menuToggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));document.addEventListener('input',e=>{if(e.target.id==='employeeSearch'){attendanceFilters.search=e.target.value;applyAttendanceFilters()}});document.addEventListener('change',e=>{if(e.target.id==='departmentFilter'){attendanceFilters.team=e.target.value;applyAttendanceFilters();return}if(e.target.id==='statusFilter'){attendanceFilters.status=e.target.value;applyAttendanceFilters();return}if(e.target.id==='shiftMode'){teamShiftMode=e.target.value;toast(teamShiftMode==='EMPLOYEE_SELECT'?'Employees can choose Shift 1 or Shift 2 at check-in.':'Manager-assigned shift mode enabled for this team.');return}if(e.target.name==='type'&&$('#leaveDurationFields')){let isPermission=e.target.value==='Permission';$('#leaveDurationFields').hidden=isPermission;$('#permissionDurationFields').hidden=!isPermission;let amount=$('input[name="permissionHours"]');if(amount)amount.required=isPermission}if(e.target.name==='duration'&&$('#halfDayDetails')){let isHalf=e.target.value==='Half day';$('#halfDayDetails').hidden=!isHalf;$('#halfDayDetails input[type="time"]').forEach(field=>field.required=isHalf)}if(e.target.matches('[data-task]')){let t=tasks.find(x=>x.title===e.target.dataset.task);if(t)t.status=e.target.value;toast(`Task moved to ${e.target.value}.`);render()}});render();
